/* Packed footage so index.html can open from disk. */
window.MEDIA = {};
window.MEDIA_READY = (async () => {
  const items = [
    ["dojo.jpg","image/jpeg",""],
    ["horsestance.mp4","video/mp4",""],
    ["simplepunch.mp4","video/mp4",""],
    ["punch.mp4","video/mp4",""],
    ["forwardkick.mp4","video/mp4",""],
    ["sidekick.mp4","video/mp4",""],
    ["hookkick.mp4","video/mp4",""],
    ["highkick.mp4","video/mp4",""],
    ["sidehighkick.mp4","video/mp4",""],
    ["headkick.mp4","video/mp4",""],
    ["jumpkick.mp4","video/mp4",""],
    ["spinkick.mp4","video/mp4",""],
    ["multikick.mp4","video/mp4",""],
    ["swingflyingkick.mp4","video/mp4",""],
    ["reelinghead.mp4","video/mp4",""],
    ["reelingchest.mp4","video/mp4",""],
    ["reelingwasit.mp4","video/mp4",""],
    ["reelingthigh.mp4","video/mp4",""],
    ["forwardcasual.mp4","video/mp4",""],
    ["forwardguarded.mp4","video/mp4",""],
    ["lowkick.mp4","video/mp4",""],
    ["ready.mp4","video/mp4",""],
    ["horsestance2.mp4","video/mp4",""],
    ["horsestance3.mp4","video/mp4",""],
 ];
  function toUrl(mime, b64) {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return URL.createObjectURL(new Blob([bytes], { type: mime }));
  }
  const total = items.length;
  for (let i = 0; i < total; i++) {
    const row = items[i];
    const name = row[0];
    if (window.notePackedFile) window.notePackedFile(name, i, total, "clips");
    else {
      const el = document.getElementById("loadstate");
      if (el) el.textContent = "Preparing " + name + "  ·  " + (i + 1) + " / " + total;
    }
    await new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 16)));
    window.MEDIA[name] = toUrl(row[1], row[2]);
    items[i] = null;
  }
})();
